type CopyLinkButtonProps = {
  slug: string;
};

export function CopyLinkButton({ slug }: CopyLinkButtonProps) {
  function handleClick() {
    const url = new URL(`/products/${slug}`, window.location.origin);
    navigator.clipboard.writeText(url.href);
  }

  return (
    <button type="button" onClick={handleClick}>
      Copy link
    </button>
  );
}

type NewsletterFormProps = {
  onSubscribe: (email: string) => void;
};

export function NewsletterForm({ onSubscribe }: NewsletterFormProps) {
  function handleSubmit(event: React.SubmitEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubscribe(String(data.get("email")));
    event.currentTarget.reset();
  }

  return (
    <form onSubmit={handleSubmit}>
      <label htmlFor="newsletter-email">Email</label>
      <input id="newsletter-email" name="email" type="email" required />
      <button type="submit">Subscribe</button>
    </form>
  );
}

import { useState } from "react";

export function QuantityPicker() {
  const [quantity, setQuantity] = useState(1);

  function handleMore() {
    setQuantity(quantity + 1);
    console.log("quantity is still", quantity);
  }

  return (
    <div>
      <span>{quantity}</span>
      <button type="button" onClick={handleMore}>
        One more
      </button>
    </div>
  );
}

import { useState } from "react";

export function AddToCart() {
  const [quantity, setQuantity] = useState(1);

  function handleAddToCart() {
    setTimeout(() => {
      console.log(`Added ${quantity} to the cart`);
    }, 3000);
  }

  return (
    <div>
      <span>{quantity}</span>
      <button type="button" onClick={() => setQuantity(quantity + 1)}>
        One more
      </button>
      <button type="button" onClick={handleAddToCart}>
        Add to cart
      </button>
    </div>
  );
}

import { useState } from "react";
import type { Product } from "../lib/products";

type SaveButtonProps = {
  product: Product;
};

export function SaveButton({ product }: SaveButtonProps) {
  if (!product.inStock) {
    return <span>Sold out</span>;
  }

  const [saved, setSaved] = useState(false);

  return (
    <button type="button" aria-pressed={saved} onClick={() => setSaved(!saved)}>
      {saved ? "Saved" : "Save for later"}
    </button>
  );
}

import { useState } from "react";

export function AddThree() {
  const [quantity, setQuantity] = useState(1);
  console.log("render with", quantity);

  function handleValues() {
    setQuantity(quantity + 1);
    setQuantity(quantity + 1);
    setQuantity(quantity + 1);
  }

  function handleUpdaters() {
    setQuantity((q) => q + 1);
    setQuantity((q) => q + 1);
    setQuantity((q) => q + 1);
  }

  return (
    <div>
      <span>{quantity}</span>
      <button type="button" onClick={handleValues}>
        Add three with values
      </button>
      <button type="button" onClick={handleUpdaters}>
        Add three with updaters
      </button>
    </div>
  );
}

import { useState } from "react";
import { findProduct, products } from "../lib/products";

type CartLine = {
  slug: string;
  quantity: number;
};

export function Cart() {
  const [lines, setLines] = useState<CartLine[]>([]);
  const itemCount = lines.reduce((sum, line) => sum + line.quantity, 0);

  function handleAdd(slug: string) {
    if (lines.some((line) => line.slug === slug)) return;
    setLines([...lines, { slug, quantity: 1 }]);
  }

  function handleQuantityChange(slug: string, quantity: number) {
    setLines(lines.map((line) => (line.slug === slug ? { ...line, quantity } : line)));
  }

  function handleRemove(slug: string) {
    setLines(lines.filter((line) => line.slug !== slug));
  }

  return (
    <section>
      <h2>Cart ({itemCount})</h2>
      {products
        .filter((product) => product.inStock)
        .map((product) => (
          <button key={product.slug} type="button" onClick={() => handleAdd(product.slug)}>
            Add {product.name}
          </button>
        ))}
      <ul>
        {lines.map((line) => (
          <li key={line.slug}>
            {findProduct(line.slug)?.name} × {line.quantity}
            <button
              type="button"
              onClick={() => handleQuantityChange(line.slug, line.quantity + 1)}
            >
              One more
            </button>
            <button type="button" onClick={() => handleRemove(line.slug)}>
              Remove
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

