import { useState } from "react";
import { formatPrice } from "../lib/format";
import { products } from "../lib/products";

type SortOrder = "name" | "price";

export function ProductSearch() {
  const [query, setQuery] = useState("");
  const [inStockOnly, setInStockOnly] = useState(false);
  const [sort, setSort] = useState<SortOrder>("name");

  const words = query.trim().toLowerCase();
  const shown = products
    .filter((p) => p.name.toLowerCase().includes(words))
    .filter((p) => !inStockOnly || p.inStock)
    .toSorted((a, b) =>
      sort === "price" ? a.priceCents - b.priceCents : a.name.localeCompare(b.name),
    );

  return (
    <section>
      <label>
        Search
        <input type="search" value={query} onChange={(e) => setQuery(e.target.value)} />
      </label>
      <label>
        <input
          type="checkbox"
          checked={inStockOnly}
          onChange={(e) => setInStockOnly(e.target.checked)}
        />
        In stock only
      </label>
      <label>
        Sort by
        <select value={sort} onChange={(e) => setSort(e.target.value as SortOrder)}>
          <option value="name">Name</option>
          <option value="price">Price</option>
        </select>
      </label>
      <ul>
        {shown.map((p) => (
          <li key={p.slug}>
            {p.name}, {formatPrice(p.priceCents)}
          </li>
        ))}
      </ul>
    </section>
  );
}

