export type CartLine = {
  slug: string;
  quantity: number;
};

export type CartAction =
  | { type: "added"; slug: string }
  | { type: "quantityChanged"; slug: string; quantity: number }
  | { type: "removed"; slug: string }
  | { type: "cleared" };

export function cartReducer(lines: CartLine[], action: CartAction): CartLine[] {
  switch (action.type) {
    case "added": {
      const existing = lines.find((line) => line.slug === action.slug);
      if (existing) {
        return lines.map((line) =>
          line.slug === action.slug ? { ...line, quantity: line.quantity + 1 } : line,
        );
      }
      return [...lines, { slug: action.slug, quantity: 1 }];
    }
    case "quantityChanged":
      return lines.map((line) =>
        line.slug === action.slug ? { ...line, quantity: action.quantity } : line,
      );
    case "removed":
      return lines.filter((line) => line.slug !== action.slug);
    case "cleared":
      return [];
  }
}

import { useReducer } from "react";
import { cartReducer } from "../lib/cart";
import { findProduct, products } from "../lib/products";

export function Cart() {
  const [lines, dispatch] = useReducer(cartReducer, []);
  const itemCount = lines.reduce((sum, line) => sum + line.quantity, 0);

  return (
    <section>
      <h2>Cart ({itemCount})</h2>
      {products
        .filter((product) => product.inStock)
        .map((product) => (
          <button
            key={product.slug}
            type="button"
            onClick={() => dispatch({ type: "added", slug: product.slug })}
          >
            Add {product.name}
          </button>
        ))}
      <ul>
        {lines.map((line) => (
          <li key={line.slug}>
            {findProduct(line.slug)?.name} × {line.quantity}
            <button
              type="button"
              onClick={() => dispatch({ type: "removed", slug: line.slug })}
            >
              Remove
            </button>
          </li>
        ))}
      </ul>
      <button type="button" onClick={() => dispatch({ type: "cleared" })}>
        Empty cart
      </button>
    </section>
  );
}
